# Generated by manage.py generate_test_cases.
from django.contrib.auth import get_user_model
from django.test import override_settings

from bloomerp.config.definition import BloomerpAuthSettings, BloomerpConfig, InteractiveAuthSettings
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestRegisterView(BloomerpAPIViewTestCase):
    """Tests class `RegisterView` from `bloomerp/views/api/auth/register.py`."""

    view_name = 'api_register'

    def get_test_scenarios(self) -> list[RequestScenario]:
        complete_user = {
            "username": "janedoe",
            "email": "jane@example.com",
            "password": "testpass123",
            "first_name": "Jane",
            "last_name": "Doe",
        }
        return [
            RequestScenario(
                name="Registration endpoint is disabled by default",
                description=(
                    "UC: A deployment has not enabled public registration.\n"
                    "Expected Result: Registration returns 404 and explains that it is disabled."
                ),
                method="POST",
                content_type="application/json",
                data=complete_user,
                expected=ExpectedResult(
                    status_code=404,
                    response_validators=self.json_key_equals(
                        "detail", "Registration endpoints are disabled."
                    ),
                ),
            ),
            RequestScenario(
                name="Enabled registration creates and logs in user",
                description=(
                    "UC: Public signup is enabled and a visitor supplies all required fields.\n"
                    "Expected Result: The user is created and returned as authenticated."
                ),
                method="POST",
                content_type="application/json",
                data=complete_user,
                prepare=self.enable_registration,
                cleanup=self.disable_settings_override,
                expected=ExpectedResult(
                    status_code=201,
                    response_validators=self.registered_user_is_authenticated,
                ),
            ),
            RequestScenario(
                name="Registration works with multiple authentication backends",
                description=(
                    "UC: A deployment configures more than one authentication backend.\n"
                    "Expected Result: A newly registered user is still logged in."
                ),
                method="POST",
                content_type="application/json",
                data={**complete_user, "username": "janedoe2", "email": "jane2@example.com"},
                prepare=self.enable_registration_with_multiple_backends,
                cleanup=self.disable_settings_override,
                expected=ExpectedResult(
                    status_code=201,
                    response_validators=self.json_key_equals("authenticated", True),
                ),
            ),
            RequestScenario(
                name="Registration requires all user creation fields",
                description=(
                    "UC: A visitor omits a required user field during signup.\n"
                    "Expected Result: Registration returns a field-specific validation error."
                ),
                method="POST",
                content_type="application/json",
                data={"username": "janedoe", "password": "testpass123"},
                prepare=self.enable_registration,
                cleanup=self.disable_settings_override,
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=lambda response: "email" in response.json().get("detail", {}),
                ),
            ),
        ]

    def enable_registration(self, _scenario):
        self.enable_registration_settings()

    def enable_registration_with_multiple_backends(self, _scenario):
        self.enable_registration_settings(
            AUTHENTICATION_BACKENDS=[
                "django.contrib.auth.backends.ModelBackend",
                "django.contrib.auth.backends.ModelBackend",
            ]
        )

    def enable_registration_settings(self, **extra_settings):
        self.settings_override = override_settings(
            BLOOMERP_CONFIG=BloomerpConfig(
                auto_generate_api_endpoints=True,
                auth=BloomerpAuthSettings(
                    interactive=InteractiveAuthSettings(signup_enabled=True)
                ),
            ),
            **extra_settings,
        )
        self.settings_override.enable()

    def disable_settings_override(self, _scenario):
        self.settings_override.disable()

    @staticmethod
    def registered_user_is_authenticated(response):
        payload = response.json()
        return (
            payload.get("authenticated") is True
            and payload["user"]["username"] == "janedoe"
            and payload["user"]["email"] == "jane@example.com"
            and get_user_model().objects.filter(username="janedoe").exists()
        )
